int foundry_bush_v1_species_find(const char *name) {
  static const char *const names[] = {"blackberry", "blueberry", "boxwood", "buttonbush", "creosote", "elderberry", "hazel", "hibiscus", "holly", "juniper", "oleander", "palmetto", "rhododendron", "sagebrush"};
  for (int i = 0; name && i < 14; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_bush_v1_age_find(const char *name) {
  static const char *const names[] = {"young", "mature", "old"};
  for (int i = 0; name && i < 3; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_bush_v1_season_find(const char *name) {
  static const char *const names[] = {"winter", "spring", "summer", "fall"};
  for (int i = 0; name && i < 4; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_bush_v1_detail_find(const char *name) {
  static const char *const names[] = {"high", "medium", "low"};
  for (int i = 0; name && i < 3; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

bool foundry_bush_v1_fruit_applies(foundry_bush_v1_species species) {
  Params p;
  foundry_bush_v1_default_params(&p);
  p.species = species;
  return applies_fruit(p);
}

foundry_status foundry_bush_v1_get_result(foundry_runtime *rt, foundry_instance instance, foundry_bush_v1_result *out) {
  uint32_t bits = 0;
  const runtime::Status st = rt->world.result(instance, bits);
  if (st != runtime::Status::ok) return foundry_status_of(st);
  if (!out) return FOUNDRY_OK;
  out->ready = (bits & runtime::World::kResultReady) != 0;
  return FOUNDRY_OK;
}

